import { cities } from "../cities.js";

let searchQuery = "";
let filteredCities = cities.filter(city =>
  city.toLowerCase().includes(searchQuery.toLowerCase())
);

<input
  id="q"
  type="text"
  placeholder="Search cities..."
  on-input(event) {
    searchQuery = event.target.value;
  }
/>

<ul id="results">
  <for|city| of=filteredCities>
    <li>${city}</li>
  </for>
</ul>

<div id="count">${filteredCities.length} matches</div>

export default function middleware(input) {
  const url = new URL(input.request.url, 'http://localhost');
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    input.response.statusCode = 401;
    input.response.setHeader('content-type', 'text/plain');
    input.response.end('unauthorized');
  }
}

export async function onRequest({ request }) {
  const url = new URL(request.url);
  const key = url.searchParams.get('key');

  if (key !== 'letmein') {
    return new Response('unauthorized', { status: 401 });
  }
}

export default function (context, next) {
  if (context.url.searchParams.get("key") !== "letmein") {
    return new Response("unauthorized", { status: 401 });
  }
  return next();
}

export default function (context, next) {
  if (context.url.searchParams.get("key") !== "letmein") {
    return new Response("unauthorized", { status: 401 });
  }
  return next();
}

function authHandler(context, next) {
  if (context.url.searchParams.get("key") !== "letmein") {
    return new Response("unauthorized", { status: 401 });
  }
  return next();
}

export function GET(context, next) {
  return authHandler(context, next);
}

export function POST(context, next) {
  return authHandler(context, next);
}

export function PUT(context, next) {
  return authHandler(context, next);
}

export function DELETE(context, next) {
  return authHandler(context, next);
}

function checkAuth(context) {
  const key = context.url.searchParams.get("key");
  if (key !== "letmein") {
    return new Response("unauthorized", { status: 401 });
  }
}

export function GET(context, next) {
  const authError = checkAuth(context);
  if (authError) return authError;
  return next();
}

export function POST(context, next) {
  const authError = checkAuth(context);
  if (authError) return authError;
  return next();
}

export function PUT(context, next) {
  const authError = checkAuth(context);
  if (authError) return authError;
  return next();
}

export function DELETE(context, next) {
  const authError = checkAuth(context);
  if (authError) return authError;
  return next();
}
